sketch:
// genex.toml: [animation] enabled = true
// assets/kits/soldier.glb: the kit, copied from docs/examples/soldier/; soldier.py makes it
// src/facets/soldier.rs, cut down from the whole facet in docs/examples/soldier/src/facets/: a remote soldier
// animated from its replicated state alone, so every machine shows the same soldier.
use genex::animation::{FloatParam, LayerId, Mask, Motion, TriggerParam, height_ground};
use genex::prelude::*;

/// What the network carries (World holds one per remote soldier): counters, not events.
#[derive(Clone, Copy, Default)]
pub struct SoldierNet { pub pos: Vec3, pub vel: Vec3, pub yaw: f32, pub pitch: f32, pub shots: u32, pub hp: f32 }

struct Kit { animator: Animator, gait: FloatParam, fire: TriggerParam, aim_up: LayerId, seen_shots: u32 }

pub fn wire(game: &mut Game<super::World>) {
    game.on_reset(|sim, _, _, gfx| {
        let Ok(kit) = gfx.character("kits/soldier.glb") else { return };
        let (Some(idle), Some(walk), Some(aim), Some(up), Some(fire)) = (kit.clip("Idle"), kit.clip("Walk"), kit.clip("RifleAim"), kit.clip("RifleAimUp"), kit.clip("RifleFire")) else { return };
        let Some(upper_chest) = kit.skeleton().find("upper_chest") else { return };
        let mut g = kit.graph();
        let gait = g.float("gait", 0.0);
        let base = g.layer("base");
        let standing = g.state(base, "idle", Motion::clip(idle));
        let walking = g.state(base, "walk", Motion::clip(walk)); // + run, back (Walk at -1), strafes, crouch, death
        g.transition(standing, walking).when(gait.above(0.5)).inertialize(0.25);
        g.transition(walking, standing).when(gait.below(0.5)).inertialize(0.25);
        // The rifle rides the upper body (upper_chest and below it), over whatever the legs do.
        let upper = g.layer("upper");
        g.layer_mask(upper, Mask::Joints(vec![upper_chest]));
        g.state(upper, "aim", Motion::clip(aim));
        // The pitch: an additive layer weighted by it (a second one tilts down).
        let aim_up = g.layer("aim-up");
        g.layer_mask(aim_up, Mask::Joints(vec![upper_chest]));
        g.layer_additive(aim_up, aim);
        g.state(aim_up, "aim-up", Motion::clip(up));
        let shots = g.layer("shots");
        g.layer_additive(shots, fire);
        let none = g.state(shots, "none", Motion::Empty);
        let firing = g.state(shots, "fire", Motion::clip(fire).once());
        let shot = g.trigger("fire");
        g.transition(none, firing).when(shot.fired()).crossfade(0.0);
        g.transition(firing, none).at_end().crossfade(0.03);
        let Ok(graph) = g.build() else { return };
        let Ok(animator) = kit.animator(&graph) else { return };
        sim.world.kit = Some(Kit { animator, gait, fire: shot, aim_up, seen_shots: 0 });
    });
    game.on_update(|sim, ctx| {
        let net = sim.world.remote; // the last packet's state
        let Some(kit) = sim.world.kit.as_mut() else { return };
        kit.animator.set_float(kit.gait, if net.vel.length() > 0.3 { 1.0 } else { 0.0 });
        kit.animator.set_layer_weight(kit.aim_up, (net.pitch / 0.52).clamp(0.0, 1.0));
        if net.shots != kit.seen_shots { kit.animator.fire(kit.fire); kit.seen_shots = net.shots; }
        kit.animator.update(ctx.dt);
        kit.animator.plant_feet(placed(&net), height_ground(|_, _| Some(0.0)));
    });
    game.on_draw(|sim, frame, _| {
        let Some(kit) = &sim.world.kit else { return };
        let at = placed(&sim.world.remote);
        frame.tag("soldier").id(0x534f_4c44).character(&kit.animator, at).end_id();
        // The muzzle flash comes from the soldier's own rifle: kit.animator.socket(muzzle, at.matrix()).
    });
}

/// The soldier at its position, turned to its yaw about +y (0 along +x); the kit faces +z.
fn placed(net: &SoldierNet) -> Transform {
    Transform::from_translation(net.pos).with_rotation(Quat::from_rotation_y(std::f32::consts::FRAC_PI_2 - net.yaw))
}
